<script setup lang="ts">
import { computed, ref } from 'vue'
import { Inbox, X, Send, Maximize2, Minimize2, File } from 'lucide-vue-next'
import { backend, errorMessage } from '../services/backend'
const props=defineProps<{snapshot:Record<string,any>|null}>()
const expanded=ref(false),error=ref(''),busy=ref(false),showTargets=ref(false)
const files=computed<any[]>(()=>props.snapshot?.shelf?.files??[])
const targets=computed<any[]>(()=>props.snapshot?.devices?.filter((d:any)=>d.trusted&&d.connected&&!d.blocked)??[])
async function action(name:string,params:Record<string,unknown>={}){busy.value=true;error.value='';try{await backend.invoke(name,params)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><section class="shelf" :class="{expanded}"><header><button class="icon-button" title="清空并关闭" :disabled="busy" @click="action('shelf.clear')"><X :size="13"/></button><span class="drag-handle"/><button class="icon-button" title="发送到设备" :disabled="!files.length||busy" @click="showTargets=!showTargets"><Send :size="13"/></button><button class="icon-button" :title="expanded?'收起暂存区':'展开暂存区'" @click="expanded=!expanded"><component :is="expanded?Minimize2:Maximize2" :size="13"/></button></header><p v-if="error" class="notice" role="alert">{{error}}</p><div v-if="snapshot?.shelf?.preparing" class="empty-state">正在准备发送…</div><div v-else-if="!files.length" class="empty-state"><Inbox :size="40"/><h2>拖入文件</h2><p>文件会暂存在这里，拖出即可取用</p><small v-if="!snapshot?.shelf">暂存服务尚未连接</small></div><div v-else class="shelf-files" :class="{grid:expanded}"><div v-for="file in [...files].reverse()" :key="file.id||file.path" class="file-entry" @click="expanded=true"><File :size="expanded?48:92"/><span>{{file.name||file.path?.split('/').pop()}}</span><button v-if="expanded" class="icon-button" title="移除" @click.stop="action('shelf.remove',{id:file.id,path:file.path})"><X :size="12"/></button></div></div><footer v-if="files.length&&!expanded"><div><h2>{{files.length}} 个项目</h2><small>拖出全部文件</small></div><button class="button" @click="expanded=true">查看全部</button></footer><div v-if="showTargets" class="targets card"><p v-if="!targets.length">没有可发送的在线设备</p><button v-for="device in targets" :key="device.id" class="button" @click="action('shelf.send',{peer_id:device.id})">{{device.name}}</button></div></section></template>
<style scoped>.shelf{position:relative;display:flex;flex-direction:column;width:240px;min-height:240px;border:1px solid var(--line);border-radius:16px;background:var(--surface);margin:auto;overflow:hidden;box-shadow:0 8px 30px #0002}.shelf.expanded{width:480px;min-height:420px}header{display:flex;align-items:center;gap:8px;padding:12px 12px 4px}.drag-handle{flex:1;align-self:stretch;--app-region:drag}.empty-state{min-height:190px;padding:16px;gap:10px}.empty-state p{font-size:11px}.shelf-files{display:flex;justify-content:center;flex:1;padding:14px;overflow:auto}.shelf-files.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.shelf-files>.file-entry{display:flex;align-items:center;flex-direction:column;gap:5px;color:var(--accent)}.shelf-files>.file-entry span{font-size:11px;color:var(--text);max-width:85px;overflow:hidden;overflow-wrap:anywhere}footer{display:flex;justify-content:space-between;padding:0 14px 12px}.targets{position:absolute;right:12px;top:45px;display:flex;flex-direction:column;gap:8px}.notice{font-size:11px;margin:8px}</style>
